def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--verify', action='store_true')
    mode.add_argument('--install', action='store_true')
    mode.add_argument('--list', action='store_true')
    args = parser.parse_args()
    if args.list:
        for name in sorted(SOURCES):
            print(name)
        return 0
    for name, contents in sorted(SOURCES.items()):
        digest = hashlib.sha256(contents.encode('utf-8')).hexdigest()
        if digest != EXPECTED_SHA256[name]:
            raise ValueError('Checksum mismatch: '+name)
    if args.verify:
        print(f'PASS: {len(SOURCES)} embedded UTF-8 files verified')
        return 0
    root = pathlib.Path(__file__).resolve().parent
    for name, contents in sorted(SOURCES.items()):
        rel = pathlib.PurePosixPath(name)
        if rel.is_absolute() or '..' in rel.parts:
            raise ValueError('Unsafe path: '+name)
        dest = root.joinpath(*rel.parts)
        if dest.exists():
            if dest.read_bytes() != contents.encode('utf-8'):
                raise FileExistsError(f'Refusing to overwrite different file: {dest}')
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(contents, encoding='utf-8', newline='')
        print('Installed:', name)
    print(f'PASS: {len(SOURCES)} source files installed/verified')
    return 0

if __name__ == '__main__':
    sys.exit(main())
